# -*- coding: utf-8 -*-
import json
R=json.load(open('src/data/readings.json',encoding='utf-8')); RD={x['id']:x for x in R}
G=json.load(open('src/data/quickGames.json',encoding='utf-8')); GD={x['id']:x for x in G}

def reading_step(rid):
    r=RD[rid]
    return f"קוראים בקול:\n\n״{r['title']}״\n\n{r['text']}"
def game_step(gid, how, after):
    g=GD[gid]
    return f"״{g['name']}״ (משחק מוכר, בלי קישור לנושא).\n\n{g['description']}\n\n{how}\n\nאחרי המשחק שואלים: {after}"

def make(a):
    t=a['times']
    flow=[
     {"label":f"פתיחה ({t[0]} דק׳)","body":a['opening']},
     {"label":f"משחק ({t[1]} דק׳)","body":(game_step(a['game'],a['game_how'],a['game_after']) if 'game' in a else '')},
     {"label":f"מתודה ({t[2]} דק׳)","body":a['method']},
     {"label":f"קטע קריאה ({t[3]} דק׳)","body":reading_step(a['reading'])},
     {"label":f"דיון ({t[4]} דק׳)","items":a['discussion']},
     {"label":f"הסבר ({t[5]} דק׳)","body":a['explain']},
     {"label":f"סיכום ({t[6]} דק׳)","body":a['summary']},
    ]
    if a.get('no_game'):
        flow=[s for s in flow if not s['label'].startswith('משחק')]
        flow.insert(1,{"label":f"פתיחה שקטה ({t[1]} דק׳)","body":a['quiet']})
    return dict(id=a['id'],title=a['title'],categorySlug='activities',subtopics=a['subtopics'],ageLabel=a['ageLabel'],ageMin=a['ageMin'],ageMax=a['ageMax'],
      duration=sum(t),groupSize=a.get('groupSize','8–25 חניכים'),equipment=a.get('equipment',[]),shabbat=a['shabbat'],place='פנים',energy=a.get('energy','בינונית'),depth=a.get('depth','בינוני'),
      values=a['values'],tags=a['tags'],rating=4.5,character=a.get('character','C'),description=a['description'],goals=a['goals'],opening=a['opening'],
      game=(game_step(a['game'],a['game_how'],a['game_after']) if not a.get('no_game') else ''),method=a['method'],discussion=a['discussion'],
      guideNotes='',summary=a['summary'],tip=a['tip'],shabbatNote=a['shabbatNote'],flow=flow)

